-- Appeal protocol (appeal-protocol capability): the conversation of a decided appeal, generated by
-- the backend from the stored case events and kept as evidence of the new kind TRANSCRIPT.
--
-- EvidenceKind is an ordinal smallint with no CHECK constraint (see .claude/rules/database.md), so the
-- kind TRANSCRIPT (ordinal 5) needs no schema change. A TRANSCRIPT item holds a pair of files, the
-- text in file_key and the JSON in json_file_key; the second file's size and digest are new columns.
-- No backfill: existing evidence rows are untouched.
ALTER TABLE evidence_items
    ADD COLUMN json_file_key varchar(255),
    ADD COLUMN json_file_size bigint,
    ADD COLUMN json_file_sha256 varchar(64);
CREATE INDEX idx_evidence_items_json_file_key ON evidence_items (json_file_key);

-- One row per stored protocol version. status is ACTIVE (the latest), SUPERSEDED (an earlier one, kept
-- so staff can see what the record said before), PURGE_PENDING (a redaction made it unreadable at
-- once, its files are about to be deleted) or PURGED (files deleted; the row stays as a tombstone so a
-- version number is never reused). Validated by the application, not by a CHECK constraint.
--
-- evidence_id is ON DELETE SET NULL, not CASCADE: deleting the evidence of a purged version must leave
-- the tombstone behind. A deleted punishment still removes its rows (punishment_identifier cascades).
-- appeal_id has no foreign key: an appeal row is never deleted on its own, and the case timeline
-- keeps its id the same way.
CREATE TABLE appeal_protocol (
    identifier uuid NOT NULL,
    punishment_identifier varchar(255) NOT NULL,
    appeal_id uuid NOT NULL,
    version integer NOT NULL,
    evidence_id uuid,
    source_digest varchar(64) NOT NULL,
    entry_count integer NOT NULL,
    first_seq bigint,
    last_seq bigint,
    status varchar(16) NOT NULL,
    created_at bigint NOT NULL,
    purged_at bigint,
    CONSTRAINT appeal_protocol_pkey PRIMARY KEY (identifier),
    CONSTRAINT fk_appeal_protocol_punishment FOREIGN KEY (punishment_identifier)
        REFERENCES punishments (identifier) ON DELETE CASCADE,
    CONSTRAINT fk_appeal_protocol_evidence FOREIGN KEY (evidence_id)
        REFERENCES evidence_items (identifier) ON DELETE SET NULL
);
CREATE UNIQUE INDEX uq_appeal_protocol_version ON appeal_protocol (appeal_id, version);
-- The same source digest is stored once per appeal while it is readable. A purged version is excluded
-- on purpose: after an erasure of authors the regenerated version has the same digest.
CREATE UNIQUE INDEX uq_appeal_protocol_digest ON appeal_protocol (appeal_id, source_digest)
    WHERE status IN ('ACTIVE', 'SUPERSEDED');
CREATE UNIQUE INDEX uq_appeal_protocol_active ON appeal_protocol (appeal_id) WHERE status = 'ACTIVE';
CREATE INDEX idx_appeal_protocol_punishment ON appeal_protocol (punishment_identifier);
CREATE INDEX idx_appeal_protocol_evidence ON appeal_protocol (evidence_id);
CREATE INDEX idx_appeal_protocol_purge ON appeal_protocol (status) WHERE status = 'PURGE_PENDING';
